28	import org.slf4j.Logger;
29	import org.slf4j.LoggerFactory;
30	import org.springframework.http.HttpHeaders;
31	import org.springframework.http.HttpStatus;
32	import org.springframework.http.ResponseEntity;
33	import org.springframework.samples.petclinic.mapper.OwnerMapper;
34	import org.springframework.samples.petclinic.mapper.PetMapper;
35	import org.springframework.samples.petclinic.mapper.VisitMapper;
36	import org.springframework.samples.petclinic.model.Owner;
37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /** Dedicated audit logger; each successful owner create emits one line here. */
65	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper) {
79	        this.clinicService = clinicService;
80	        this.ownerMapper = ownerMapper;
81	        this.petMapper = petMapper;
82	        this.visitMapper = visitMapper;
83	    }
84	
85	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
86	    @Override
87	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
88	        Collection<Owner> owners;
89	        if (lastName != null) {
90	            owners = this.clinicService.findOwnerByLastName(lastName);
91	        } else {
92	            owners = this.clinicService.findAllOwners();
93	        }
94	        if (owners.isEmpty()) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
103	        Owner owner = this.clinicService.findOwnerById(ownerId);
104	        if (owner == null) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
108	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
109	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
115	        HttpHeaders headers = new HttpHeaders();
116	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
117	        String address = normalizeAddress(owner.getAddress());
118	        if (address.isEmpty()) {
119	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
120	        }
121	        owner.setAddress(address);
122	        String telephone = toE164(owner.getTelephone());
123	        if (telephone == null) {
124	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
125	        }
126	        owner.setTelephone(telephone);
127	        if (owner.getEmail() != null) {
128	            String email = normalizeEmail(owner.getEmail());
129	            if (email == null) {
130	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	            }
132	            owner.setEmail(email);
133	        }
134	        if (owner.getPostcode() != null && !isValidPostcode(owner.getPostcode(), owner.getCity())) {
135	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
136	        }
137	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
138	        if (effectiveRegistrationDate == null) {
139	            effectiveRegistrationDate = LocalDate.now();
140	        }
141	        else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
142	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
143	        }
144	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
145	        owner.setRegistrationDate(registrationDate);
146	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
147	            return new ResponseEntity<>(HttpStatus.CONFLICT);
148	        }
149	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
150	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
151	        }
152	        // The householdId is deterministic: the first twelve hex characters of SHA-256 over
153	        // '<normalizedLastName>|<postcode>'. Owners sharing a last name and postcode therefore
154	        // share the household automatically. An owner without a postcode has no household.
155	        boolean declaredHouseholdMember = false;
156	        if (owner.getPostcode() != null) {
157	            String householdId = householdId(householdKey(owner.getLastName()), owner.getPostcode());
158	            owner.setHouseholdId(householdId);
159	            // Because the household is now keyed on (lastName, postcode), a second owner in the
160	            // same household is a household duplicate: rejected with 409 unless it opts in with
161	            // 'sharesHousehold', in which case it is created as a declared household member.
162	            boolean householdOccupied = false;
163	            for (Owner existing : this.clinicService.findAllOwners()) {
164	                if (householdId.equals(computeHouseholdId(existing))) {
165	                    householdOccupied = true;
166	                    break;
167	                }
168	            }
169	            if (householdOccupied) {
170	                if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
171	                    return new ResponseEntity<>(HttpStatus.CONFLICT);
172	                }
173	                declaredHouseholdMember = true;
174	            }
175	        }
176	        // Consolidated duplicate detection: reject only when the whole identityKey
177	        // (normalized telephone | email | householdId) matches an existing owner's.
178	        String identityKey = identityKey(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
179	        for (Owner existing : this.clinicService.findAllOwners()) {
180	            if (identityKey.equals(identityKey(toE164(existing.getTelephone()),
181	                emailForKey(existing.getEmail()), existing.getHouseholdId()))) {
182	                return new ResponseEntity<>(HttpStatus.CONFLICT);
183	            }
184	        }
185	        // Soft-match: the owner is not a hard (identityKey) duplicate, but if it shares an
186	        // existing owner's last name and postcode while having a different normalized
187	        // telephone it is still created and flagged as a possible duplicate of that owner. A
188	        // declared household member, however, is not a suspected duplicate, so it is never flagged.
189	        if (declaredHouseholdMember) {
190	            owner.setPossibleDuplicate(false);
191	        }
192	        else {
193	            applyPossibleDuplicate(owner);
194	        }
195	        owner.setCustomerCode(customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName()));
196	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
197	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
198	        this.clinicService.saveOwner(owner);
199	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
200	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
201	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
202	            ownerDto.getMembershipLevel());
203	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
204	        headers.setLocation(UriComponentsBuilder.newInstance()
205	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
206	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
207	    }
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
212	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
213	        if (currentOwner == null) {
214	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
215	        }
216	        currentOwner.setAddress(ownerFieldsDto.getAddress());
217	        currentOwner.setCity(ownerFieldsDto.getCity());
218	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
219	        currentOwner.setLastName(ownerFieldsDto.getLastName());
