302	    /**
303	     * The maximum number of owners permitted per city. Owner creation is rejected once the
304	     * owner's city already contains this many owners.
305	     */
306	    private static final int MAX_OWNERS_PER_CITY = 50;
307	
308	    /**
309	     * Counts how many existing owners live in the given city, compared case-insensitively.
310	     * This is evaluated before the new owner is persisted, so the owner being created is not
311	     * included in the count.
312	     *
313	     * @param city the new owner's city
314	     * @return the number of existing owners in that city
315	     */
316	    private int countOwnersInCity(String city) {
317	        int count = 0;
318	        for (Owner existing : this.clinicService.findAllOwners()) {
319	            if (city.equalsIgnoreCase(existing.getCity())) {
320	                count++;
321	            }
322	        }
323	        return count;
324	    }
325	
326	    /**
327	     * The maximum number of owners that may be created in a single business day. Owner
328	     * creation is rejected once this many owners already fall on the new owner's adjusted
329	     * business day {@code registrationDate}.
330	     */
331	    private static final int MAX_OWNERS_PER_DAY = 100;
332	
333	    /**
334	     * Rolls a date forward to the next business day: a Saturday or Sunday is moved forward
335	     * to the following Monday, while a weekday is returned unchanged.
336	     *
337	     * @param date the date to adjust
338	     * @return the same date if it is a weekday, otherwise the following Monday
339	     */
340	    private LocalDate toBusinessDay(LocalDate date) {
341	        DayOfWeek dayOfWeek = date.getDayOfWeek();
342	        if (dayOfWeek == DayOfWeek.SATURDAY) {
343	            return date.plusDays(2);
344	        }
345	        if (dayOfWeek == DayOfWeek.SUNDAY) {
346	            return date.plusDays(1);
347	        }
348	        return date;
349	    }
350	
351	    /**
352	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
353	     * registrationDate} rolls forward to the same business day. This is evaluated before the
354	     * new owner is persisted, so the owner being created is not included in the count.
355	     *
356	     * @param businessDay the adjusted business day to count against
357	     * @return the number of existing owners registered on that business day
358	     */
359	    private int countOwnersRegisteredOn(LocalDate businessDay) {
360	        int count = 0;
361	        for (Owner existing : this.clinicService.findAllOwners()) {
362	            LocalDate existingDate = existing.getRegistrationDate();
363	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
364	                count++;
365	            }
366	        }
367	        return count;
368	    }
369	
370	    /**
371	     * The number of owners that may be created on a single business day before a bulk-signup
372	     * warning is raised. Once more than this many owners already fall on the current business
373	     * day, {@code bulkSignupWarning} is reported as {@code true} in the owner response.
374	     */
375	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
376	
377	    /**
378	     * Reports whether an unusually high number of owners have been created for today's business
379	     * day, i.e. whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already fall on
380	     * the business day that {@code LocalDate.now()} rolls forward to.
381	     *
382	     * @return {@code true} once more than 80 owners have been created today, otherwise {@code false}
383	     */
384	    private boolean isBulkSignupDay() {
385	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > BULK_SIGNUP_WARNING_THRESHOLD;
386	    }
387	
388	    /**
389	     * Builds the customer code for a newly created owner, formatted
390	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the canonical region
391	     * {@link OwnerLocality#forPostcodeOrUnknown derived from the postcode} (or
392	     * {@code "UNKNOWN"} when the postcode resolves no region) and {@code HASH8} is the
393	     * first eight upper-case hex characters of the SHA-256 digest of
394	     * {@code normalizedTelephone + lastName}. The code carries no sequence number, so it is
395	     * stable for a given telephone and last name rather than dependent on creation order.
396	     *
397	     * @param postcode            the owner's postcode (may be {@code null})
398	     * @param normalizedTelephone the owner's normalized E.164 telephone
399	     * @param lastName            the owner's last name
400	     * @return the assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
401	     */
402	    private static String customerCode(String postcode, String normalizedTelephone, String lastName) {
403	        String region = org.springframework.samples.petclinic.mapper.OwnerLocality.forPostcodeOrUnknown(postcode);
404	        return region + "-" + sha256Hex8(normalizedTelephone + lastName);
405	    }
406	
407	    /**
408	     * Returns the first eight upper-case hex characters of the SHA-256 digest of the UTF-8
409	     * bytes of {@code source} — the {@code HASH8} component of an owner's customer code.
410	     *
411	     * @param source the string to hash
412	     * @return the first eight upper-case hex characters of {@code SHA-256(source)}
413	     */
414	    private static String sha256Hex8(String source) {
415	        try {
416	            byte[] digest = MessageDigest.getInstance("SHA-256")
417	                .digest(source.getBytes(StandardCharsets.UTF_8));
418	            StringBuilder hex = new StringBuilder(digest.length * 2);
419	            for (byte b : digest) {
420	                hex.append(String.format("%02x", b));
421	            }
422	            return hex.substring(0, 8).toUpperCase();
423	        } catch (NoSuchAlgorithmException e) {
424	            throw new IllegalStateException("SHA-256 not available", e);
425	        }
426	    }
427	
428	    /**
429	     * Builds the membership number for a newly created owner, formatted
430	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
431	     * customer code and {@code YY} is the last two digits of the owner's registration
432	     * date year, zero-padded to two digits.
433	     *
434	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
435	     * @param registrationDate the owner's registration date
436	     * @return the assigned membership number (e.g. {@code 'NSW-1A2B3C4D-M26'})
437	     */
438	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
439	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
440	    }
441	
442	    /**
443	     * Counts how many existing owners share the given first and last name, compared
444	     * case-insensitively. This is evaluated before the new owner is persisted, so the
445	     * owner being created is not included in the count.
446	     *
447	     * @param firstName the new owner's first name
448	     * @param lastName  the new owner's last name
449	     * @return the number of existing owners with the same first and last name
450	     */
451	    private int countNamesakes(String firstName, String lastName) {
452	        int count = 0;
453	        for (Owner existing : this.clinicService.findAllOwners()) {
454	            if (firstName.equalsIgnoreCase(existing.getFirstName())
455	                && lastName.equalsIgnoreCase(existing.getLastName())) {
456	                count++;
457	            }
458	        }
459	        return count;
460	    }
461	
462	    /**
463	     * Canonical expansions applied to common street-type abbreviations during address
464	     * normalization. Keys and values are upper-cased so the lookup runs after the address
465	     * has itself been upper-cased.
466	     */
467	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
468	        "ST", "STREET",
469	        "RD", "ROAD",
470	        "AVE", "AVENUE");
471	
472	    /**
473	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
474	     * every run of internal whitespace is collapsed to a single space, the result is
475	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
476	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
477	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
478	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
479	     * returned and compared for household duplicates; an address that is blank once
480	     * normalized fails the required-field check.
481	     *
482	     * @param address the raw address value supplied by the client
483	     * @return the normalized address (empty string when {@code address} is null or blank)
484	     */
485	    private static String normalizeAddress(String address) {
486	        if (address == null) {
487	            return "";
488	        }
489	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
490	        if (collapsed.isEmpty()) {
491	            return "";
492	        }
493	        StringBuilder normalized = new StringBuilder(collapsed.length());
494	        for (String token : collapsed.split(" ")) {
495	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
496	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
497	            if (normalized.length() > 0) {
498	                normalized.append(' ');
499	            }
500	            normalized.append(expanded != null ? expanded : token);
501	        }
502	        return normalized.toString();
503	    }
504	
505	    /**
506	     * Normalizes a last name or address for household-duplicate comparison: leading and
507	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
508	     * single space and the result is lower-cased. Two owners are considered to share a
509	     * household when both their last names and addresses produce the same key.
510	     *
511	     * @param value the raw last name or address value
512	     * @return the normalized comparison key (empty string when {@code value} is null)
513	     */
514	    private static String householdKey(String value) {
515	        if (value == null) {
516	            return "";
517	        }
518	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
519	    }
520	
521	    /**
522	     * Derives the stable shared household identifier for the given normalized last name key
523	     * and postcode. The identifier is deterministic — the same household (same
524	     * {@link #householdKey normalized} last name and postcode) always maps to the same
525	     * value — so every owner in a household is assigned an identical id. It is the
526	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
527	     * '<lastNameKey>|<postcode>'}.
528	     *
529	     * @param lastNameKey the normalized last name key
530	     * @param postcode    the owner's postcode
531	     * @return the shared household identifier
532	     */
533	    private static String householdId(String lastNameKey, String postcode) {
534	        String source = lastNameKey + "|" + postcode;
535	        try {
536	            byte[] digest = MessageDigest.getInstance("SHA-256")
537	                .digest(source.getBytes(StandardCharsets.UTF_8));
538	            StringBuilder hex = new StringBuilder(digest.length * 2);
539	            for (byte b : digest) {
540	                hex.append(String.format("%02x", b));
541	            }
542	            return hex.substring(0, 12).toUpperCase();
543	        } catch (NoSuchAlgorithmException e) {
544	            throw new IllegalStateException("SHA-256 not available", e);
545	        }
546	    }
547	
548	    /**
549	     * Computes the deterministic {@link #householdId household id} an existing owner belongs to,
550	     * derived from its {@link #householdKey normalized} last name and its postcode. Returns
551	     * {@code null} when the owner has no postcode (such an owner has no household), so it never
552	     * collides with a computed household id.
553	     *
554	     * @param owner the existing owner
555	     * @return the owner's household id, or {@code null} when it has no postcode
556	     */
557	    private static String computeHouseholdId(Owner owner) {
558	        if (owner.getPostcode() == null) {
559	            return null;
560	        }
561	        return householdId(householdKey(owner.getLastName()), owner.getPostcode());
562	    }
563	
564	    /**
565	     * Applies soft-match (possible-duplicate) detection to a new owner that has already
566	     * cleared hard {@code identityKey} duplicate rejection. The owner is flagged as a
567	     * possible duplicate when an existing owner shares its last name (compared
568	     * case-insensitively with collapsed whitespace) and its postcode while having a
569	     * different normalized telephone; {@code possibleDuplicateOf} is then set to that
570	     * existing owner's id. When several existing owners match, the one with the lowest id
571	     * is chosen so the result is deterministic. When no such owner exists — or the new
572	     * owner has no postcode to compare — {@code possibleDuplicate} is set to {@code false}
573	     * and no matching id is recorded.
574	     *
575	     * @param owner the new owner, already normalized (E.164 telephone, validated postcode)
576	     */
577	    private void applyPossibleDuplicate(Owner owner) {
578	        owner.setPossibleDuplicate(false);
579	        if (owner.getPostcode() == null) {
580	            return;
581	        }
582	        String lastNameKey = householdKey(owner.getLastName());
583	        Owner match = null;
584	        for (Owner existing : this.clinicService.findAllOwners()) {
585	            if (lastNameKey.equals(householdKey(existing.getLastName()))
586	                && owner.getPostcode().equals(existing.getPostcode())
587	                && !owner.getTelephone().equals(toE164(existing.getTelephone()))) {
588	                if (match == null || (existing.getId() != null
589	                    && existing.getId() < match.getId())) {
590	                    match = existing;
591	                }
592	            }
593	        }
594	        if (match != null) {
595	            owner.setPossibleDuplicate(true);
596	            owner.setPossibleDuplicateOf(match.getId());
597	        }
598	    }
599	
600	    /**
601	     * Builds the derived duplicate-detection identity key from an owner's normalized
602	     * telephone, email and household id, formatted {@code
603	     * '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Two owners are
604	     * duplicates only when their whole identity keys are equal; because the telephone is
605	     * part of the key, members of the same household with different telephones produce
606	     * different keys and are both allowed.
607	     *
608	     * @param normalizedTelephone the E.164 telephone (may be {@code null})
609	     * @param email               the normalized (lower-cased) email, or {@code null} when absent
610	     * @param householdId         the shared household id, or {@code null} when the owner is not in a household
611	     * @return the identity key string
612	     */
613	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
614	        return (normalizedTelephone == null ? "" : normalizedTelephone)
615	            + "|" + (email == null ? "" : email)
616	            + "|" + (householdId == null ? "" : householdId);
617	    }
618	
619	    /**
620	     * Normalizes an existing owner's stored email for identity-key comparison: trimmed and
621	     * lower-cased, mirroring {@link #normalizeEmail} without re-validating syntax. Returns
622	     * {@code null} when the owner has no email.
623	     *
624	     * @param email the existing owner's stored email (may be {@code null})
625	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is null
626	     */
627	    private static String emailForKey(String email) {
628	        return email == null ? null : email.trim().toLowerCase();
629	    }
630	
631	    /**
632	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
633	     * and brackets are stripped. When the number already carries a leading {@code '+'}
634	     * and country code these are kept; a number written in national trunk form (a leading
635	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
636	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
637	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
638	     * after the {@code '+'}, and its national-number length must be valid for the detected
639	     * country code (see {@link #hasValidNationalLength}).
640	     *
641	     * @param telephone the raw telephone value supplied by the client
642	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
643	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
644	     */
645	    private static String toE164(String telephone) {
646	        if (telephone == null) {
647	            return null;
648	        }
649	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
650	        String digits;
651	        if (cleaned.startsWith("+")) {
652	            digits = cleaned.substring(1);
653	        } else if (cleaned.startsWith("0")) {
654	            digits = "61" + cleaned.substring(1);
655	        } else {
656	            digits = "1" + cleaned;
657	        }
658	        if (!digits.matches("[0-9]{8,15}")) {
659	            return null;
660	        }
661	        if (!hasValidNationalLength(digits)) {
662	            return null;
663	        }
664	        return "+" + digits;
665	    }
666	
667	    /**
668	     * Validates the national-number length of an E.164 digit string against its country
669	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
670	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
671	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
672	     *
673	     * @param digits the E.164 digits (without the leading {@code '+'})
674	     * @return {@code true} when the national-number length is valid for the country code
675	     */
676	    private static boolean hasValidNationalLength(String digits) {
677	        if (digits.startsWith("61")) {
678	            return digits.length() - 2 == 9;
679	        }
680	        if (digits.startsWith("1")) {
681	            return digits.length() - 1 == 10;
682	        }
683	        return true;
684	    }
685	
686	    /**
687	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
688	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
689	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
690	     */
691	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
692	        "NSW", new int[] {2000, 2099},
693	        "VIC", new int[] {3000, 3099},
694	        "QLD", new int[] {4000, 4099});
695	
696	    /**
697	     * Validates an owner's postcode for creation. A postcode is only ever validated when
698	     * present (an absent postcode is optional and accepted). When present it must be exactly
699	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
700	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
701	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
702	     *
703	     * @param postcode the supplied postcode (never {@code null} here)
704	     * @param city     the owner's city, used to derive the region
705	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
706	     *         (signalling a 400 Bad Request)
707	     */
708	    private static boolean isValidPostcode(String postcode, String city) {
709	        if (!postcode.matches("[0-9]{4}")) {
710	            return false;
711	        }
712	        int[] range = REGION_POSTCODES.get(
713	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
714	        if (range == null) {
715	            return true;
716	        }
717	        int value = Integer.parseInt(postcode);
718	        return value >= range[0] && value <= range[1];
719	    }
720	
721	    /**
722	     * Normalizes an owner email for creation. A present email must be a syntactically
723	     * valid address; the returned value is lower-cased.
724	     *
725	     * @param email the raw email value supplied by the client (never {@code null} here)
726	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
727	     *         address (signalling a 400 Bad Request)
728	     */
729	    private static String normalizeEmail(String email) {
730	        String trimmed = email.trim();
731	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
732	            return null;
733	        }
734	        return trimmed.toLowerCase();
735	    }
736	}
